  'A range title is letters, digits, spaces, dots, hyphens and underscores.': 'يتكون عنوان النطاق من أحرف وأرقام ومسافات ونقاط وواصلات وشرطات سفلية.',
  'A record for which this holds is left out of the merge.': 'يُستبعد من الدمج كل سجل يتحقق فيه هذا الشرط.',
  'A rectangle with words in it': 'مستطيل بداخله نص',
  'A rule files mail as it arrives — a newsletter into its own folder, an invoice starred, a mailing list marked read. You can see exactly what one would do before it does anything.': 'تفرز القاعدة البريد عند وصوله — رسالة إخبارية إلى مجلدها الخاص، وفاتورة تُميَّز بنجمة، وقائمة بريدية تُعلَّم كمقروءة. ويمكنك أن ترى بالضبط ما ستفعله القاعدة قبل أن تفعل أي شيء.',
  'A scatter chart here plots up to three series — select a block of an X column and up to three Y columns.': 'يرسم المخطط المبعثر هنا ما يصل إلى ثلاث سلاسل — حدد كتلة تضم عمود X وما يصل إلى ثلاثة أعمدة Y.',
  'A scheduled or held message sends when Rutba Office is running — one that falls due while it is closed goes out the next time it opens. A failed send stays here with the error and keeps retrying.': 'تُرسل الرسالة المجدولة أو المؤجلة عندما يكون Rutba Office قيد التشغيل — وما يحين موعده أثناء إغلاقه يُرسل في المرة التالية التي يُفتح فيها. وتبقى الرسالة التي فشل إرسالها هنا مع الخطأ، وتستمر محاولة إرسالها.',
  'A script cannot merge across part of a merged region': 'لا يمكن للبرنامج النصي الدمج عبر جزء من منطقة مدمجة',
  'A script cannot set a cell outside the worksheet (A1 to XFD1048576)': 'لا يمكن للبرنامج النصي تعيين خلية خارج ورقة العمل (من A1 إلى XFD1048576)',
  'A script needs a function called main(workbook)': 'يحتاج البرنامج النصي إلى دالة باسم main(workbook)',
  'A sender goes on the Safe or the Blocked list.': 'يُضاف المرسل إلى القائمة الآمنة أو إلى قائمة المحظورين.',
  'A sentence or two is usually right.': 'تكفي جملة أو جملتان عادةً.',
  'A series is linear, growth, dates or AutoFill': 'نوع السلسلة خطي أو نمو أو تاريخ أو تعبئة تلقائية',
  'A series starts from a number or a date in the first cell': 'تبدأ السلسلة من رقم أو تاريخ في الخلية الأولى',
  'A sheet of labels, each after the first starting with «Next Record». Put an Address Block in the first, then Update Labels.': 'ورقة تسميات، تبدأ كل تسمية بعد الأولى بـ«السجل التالي». ضع «كتلة العنوان» في الأولى، ثم انقر «تحديث التسميات».',
  'A sidebar stands beside the story with the words that go with it: a summary, a list of points, a note for the reader.': 'يقف الشريط الجانبي بجوار النص الرئيسي ويحمل ما يتصل به: ملخصًا، أو قائمة نقاط، أو ملاحظة للقارئ.',
  'A signature line cannot go inside a table cell yet — move the caret out of the table.': 'لا يمكن وضع سطر توقيع داخل خلية جدول بعد — انقل علامة الإدراج خارج الجدول.',
  'A slicer is not grouped with other objects here — take it out of the selection.': 'لا تُجمَّع أداة تقسيم البيانات مع كائنات أخرى هنا — أخرجها من التحديد.',
  'A slicer keeps at least one item selected — Clear Filter shows them all.': 'تُبقي أداة تقسيم البيانات عنصرًا واحدًا على الأقل محددًا — انقر «مسح عامل التصفية» لإظهار العناصر كلها.',
  'A slide with a timing of its own keeps it when timings are used; the rest stay up for the seconds above. Animations are shown finished.': 'تحتفظ الشريحة التي لها توقيت خاص بتوقيتها عند استخدام التوقيتات؛ وتبقى بقية الشرائح معروضة عدد الثواني المحدد أعلاه. وتُعرض الحركات مكتملة.',
  'A source is already tagged {tag}.': 'يوجد بالفعل مصدر يحمل العلامة {tag}.',
  'A style can be linked to one level only.': 'لا يمكن ربط النمط إلا بمستوى واحد.',
  'A table needs columns.': 'يحتاج الجدول إلى أعمدة.',
  'A table or chart frame has no fill or outline of its own.': 'ليس لإطار الجدول أو المخطط تعبئة أو مخطط تفصيلي خاص به.',
  'A table row does not fit even on an empty page; the margins leave no body.': 'لا يتسع صف الجدول حتى في صفحة فارغة؛ فالهوامش لا تترك مساحة للنص.',
  'A text box cannot be anchored in this paragraph — it is part of a field or a content control.': 'لا يمكن ربط مربع نص بهذه الفقرة — فهي جزء من حقل أو عنصر تحكم في المحتوى.',
  'A text box goes beside the words, not in a table cell — move the caret out of the table first.': 'يوضع مربع النص بجانب النص، لا في خلية جدول — انقل علامة الإدراج خارج الجدول أولاً.',
  'A title page at the front': 'صفحة عنوان في البداية',
  'A to Z': 'من أ إلى ي',
  'A to Z, small to large': 'من أ إلى ي، من الأصغر إلى الأكبر',
  'A to Z, the first row a header': 'من أ إلى ي، والصف الأول رأس',
  'A view called “{name}” exists — OK replaces it.': 'توجد طريقة عرض باسم «{name}» — انقر «موافق» لاستبدالها.',
  'A viewer that opens before you blink': 'عارض يفتح قبل أن ترمش عينك',
  'A watermark picture is a PNG, a JPEG, a GIF, a BMP or a WebP.': 'يجب أن تكون صورة العلامة المائية بتنسيق PNG أو JPEG أو GIF أو BMP أو WebP.',
  'A web address starts http:// or https://, an e-mail address mailto:.': 'يبدأ عنوان الويب بـ http:// أو https://، ويبدأ عنوان البريد الإلكتروني بـ mailto:.',
  'A web address, or mailto: for an email link.': 'عنوان ويب، أو mailto: لارتباط بريد إلكتروني.',
  'A web address, or mailto: for an email link. Ctrl+click the shape to follow it.': 'عنوان ويب، أو mailto: لارتباط بريد إلكتروني. اضغط Ctrl وانقر الشكل لتتبع الارتباط.',
  'A word is broken only where the line would otherwise end further than this from the right margin.': 'لا تُقسَّم الكلمة إلا إذا كان السطر سينتهي بدون تقسيمها على مسافة من الهامش الأيمن أبعد من هذه.',
  'A word to look up': 'كلمة للبحث عنها',
  'A workbook must contain at least one visible worksheet': 'يجب أن يحتوي المصنف على ورقة عمل مرئية واحدة على الأقل',
