  'Each category is written as Word\'s TOA field, its heading over it; All writes one for every category that has citations in it.': 'تُكتب كل فئة كحقل TOA الخاص بـ Word وعنوانها فوقه؛ ويكتب «الكل» حقلاً لكل فئة تحتوي على اقتباسات.',
