  'Each message is the merged letter itself. The account\'s signature is not added: what you wrote in the letter is what each person receives.': 'كل رسالة هي الخطاب المدمج نفسه. لا يُضاف توقيع الحساب: ما كتبته في الخطاب هو ما يتلقاه كل شخص.',
  'Each numbered level shows its own number: keep %{level} in level {level}\'s number.': 'يُظهر كل مستوى مرقّم رقمه الخاص: أبقِ %{level} في رقم المستوى {level}.',
  'Each sender hears from this once while it stays on — a second message from the same person is not answered again until it is turned off and on. A mailing list, a no-reply address and a message that already says it is automatic are never answered.': 'يتلقى كل مرسِل هذا الرد مرة واحدة ما دام قيد التشغيل — فلا يُرد على رسالة ثانية من الشخص نفسه حتى يتم إيقاف تشغيله ثم تشغيله من جديد. ولا يُرد أبداً على قائمة بريدية أو عنوان لا يقبل الردود (no-reply) أو رسالة تذكر أنها تلقائية.',
  'Each slide then moves on by itself after the time it was on screen, and Use Timings is turned on.': 'بعد ذلك تنتقل كل شريحة تلقائياً بعد المدة التي ظهرت فيها على الشاشة، ويتم تشغيل «استخدام التوقيتات».',
