  'Show Notes': 'إظهار الملاحظات',
  'Show Training': 'إظهار التدريب',
  'Show announcements from office.rutba.io — once a day at most. It sends the version and the operating system, and no identifier of any kind, so what is counted at the other end is "a copy opened somewhere", never you. It is also the only way we know the suite is being used at all.': 'إظهار الإعلانات من office.rutba.io — مرة واحدة في اليوم على الأكثر. يُرسَل رقم الإصدار ونظام التشغيل، دون أي معرّف من أي نوع، لذا فإن ما يُحسب في الطرف الآخر هو «نسخة فُتحت في مكان ما»، وليس أنت أبداً. وهي أيضاً الطريقة الوحيدة التي نعرف بها أن المجموعة تُستخدم أصلاً.',
