  'Shows a list of ideas one under the other, each in a wide rounded box.': 'يعرض قائمة من الأفكار واحدة تحت الأخرى، كل منها في مربع عريض مستدير الزوايا.',
  'Shows each top item over the items under it — a line to each. Tab a line in to put it under the one above.': 'يعرض كل عنصر علوي فوق العناصر التابعة له — مع خط إلى كل منها. اضغط Tab لإزاحة سطر إلى الداخل ووضعه تحت السطر الذي يعلوه.',
  'Shows ideas that need not follow one another, each in a box of its own, the boxes in rows.': 'يعرض أفكاراً لا يلزم أن تتبع إحداها الأخرى، كل منها في مربع خاص بها، والمربعات مرتبة في صفوف.',
  'Shows stages that come round again, in circles on a ring, clockwise from the top.': 'يعرض مراحل تتكرر بشكل دوري، في دوائر على حلقة، باتجاه عقارب الساعة بدءاً من الأعلى.',
  'Shows the stages of a process moving forward, each a chevron pointing to the next.': 'يعرض مراحل عملية تتقدم إلى الأمام، كل منها على شكل شيفرون يشير إلى المرحلة التالية.',
  'Shows the steps of a process in order, left to right, an arrow from each to the next.': 'يعرض خطوات عملية بالترتيب، من اليسار إلى اليمين، مع سهم من كل خطوة إلى التالية.',
