  'That is the table\'s own edge — there is no cell beyond it to join.': 'هذه حافة الجدول نفسها — لا توجد خلية بعدها للدمج معها.',
  'That message was sent to you, not to a group or a mailing list — Never block sender keeps its sender instead.': 'أُرسلت هذه الرسالة إليك أنت، لا إلى مجموعة أو قائمة بريدية — أما «عدم حظر المرسل مطلقًا» فيحتفظ بمرسلها بدلًا من ذلك.',
