  'The picture could not be redrawn.': 'تعذّرت إعادة رسم الصورة.',
  'The picture could not be turned: {error}': 'تعذّر تدوير الصورة: {error}',
  'The pivot table goes under the data and its chart beside it; the chart follows the pivot when it is refreshed or filtered.': 'يوضع PivotTable أسفل البيانات ومخططه بجانبه؛ ويتبع المخطط PivotTable عند تحديثه أو تصفيته.',
  'The pivot table goes under the data. Data → Refresh All recalculates it from the source.': 'يوضع PivotTable أسفل البيانات. ويعيد الأمر بيانات ← تحديث الكل حسابه من المصدر.',
