  'The script could not run': 'تعذّر تشغيل البرنامج النصي',
  'The script ran for more than {count} second and was stopped': { zero: 'استمر تشغيل البرنامج النصي أكثر من {count} ثانية وتم إيقافه', one: 'استمر تشغيل البرنامج النصي أكثر من ثانية واحدة وتم إيقافه', two: 'استمر تشغيل البرنامج النصي أكثر من ثانيتين وتم إيقافه', few: 'استمر تشغيل البرنامج النصي أكثر من {count} ثوانٍ وتم إيقافه', many: 'استمر تشغيل البرنامج النصي أكثر من {count} ثانية وتم إيقافه', other: 'استمر تشغيل البرنامج النصي أكثر من {count} ثانية وتم إيقافه' },
  'The script ran too long': 'استغرق تشغيل البرنامج النصي وقتاً طويلاً جداً',
  'The selection already contains merged cells — split them first.': 'يحتوي التحديد بالفعل على خلايا مدمجة — قم بتقسيمها أولاً.',
  'The selection holds a formula in its corner and the values to try along its edges. Each cell is filled with what the formula gives for that combination.': 'يحتوي التحديد على صيغة في زاويته وعلى القيم المراد تجربتها على امتداد حوافه. وتُملأ كل خلية بالنتيجة التي تعطيها الصيغة لتلك التركيبة من القيم.',
  'The sender supports one-click unsubscribe. A single request is sent to them and nothing else leaves this computer.': 'يدعم المرسل إلغاء الاشتراك بنقرة واحدة. يُرسل إليه طلب واحد فقط ولا يغادر هذا الكمبيوتر أي شيء آخر.',
  'The server answered {status} where a list was asked for.': 'ردّ الخادم بـ {status} بدلاً من القائمة المطلوبة.',
  'The server did not accept the user name and password.': 'لم يقبل الخادم اسم المستخدم وكلمة المرور.',
  'The server refused to keep {href}: {status}': 'رفض الخادم حفظ {href}: {status}',
  'The server refused to remove {href}: {status}': 'رفض الخادم إزالة {href}: {status}',
  'The server sent the request round in circles.': 'أعاد الخادم توجيه الطلب في حلقة مفرغة.',
