  'The show took {time}. Keep the new slide timings?': 'استغرق العرض {time}. هل تريد الاحتفاظ بتوقيتات الشرائح الجديدة؟',
  'The sign-in came back with the wrong state, so it was refused.': 'عاد تسجيل الدخول بقيمة حالة غير صحيحة، لذا تم رفضه.',
