  'There is nothing on the clipboard to paste.': 'لا يوجد شيء في الحافظة للصقه.',
  'Thesaurus': 'قاموس المرادفات',
  'Thesaurus (Shift+F7) — words of like meaning for the word at the caret, one of them put in its place': 'قاموس المرادفات (Shift+F7) — كلمات ذات معنى مماثل للكلمة الموجودة عند المؤشر، مع وضع إحداها مكانها',
  'Thesaurus (Shift+F7) — words of like meaning for the word in the active cell': 'قاموس المرادفات (Shift+F7) — كلمات ذات معنى مماثل للكلمة الموجودة في الخلية النشطة',
  'Thesaurus (Shift+F7) — words of like meaning for the word where the caret was in a shape\'s text': 'قاموس المرادفات (Shift+F7) — كلمات ذات معنى مماثل للكلمة التي كان المؤشر عندها في نص الشكل',
  'These are imported archives — there is nothing to fetch.': 'هذه أرشيفات مستوردة — لا يوجد ما يمكن جلبه.',
  'These are set with xdg-mime, which this can do directly.': 'يتم تعيين هذه باستخدام xdg-mime، ويمكن لهذا البرنامج القيام بذلك مباشرةً.',
  'These cells are part of a vertical merge — widening one row of it would tear the range.': 'هذه الخلايا جزء من دمج عمودي — سيؤدي توسيع صف واحد منه إلى تفكيك النطاق.',
  'These settings came from {source} on this computer; they are checked when the address is complete.': 'جاءت هذه الإعدادات من {source} على هذا الكمبيوتر؛ ويتم التحقق منها عند اكتمال العنوان.',
  'They are saved into the presentation, and travel with it.': 'يتم حفظها في العرض التقديمي، وتنتقل معه.',
