  'This account': 'هذا الحساب',
  'This action will not be marked as a change.': 'لن يتم تمييز هذا الإجراء كتغيير.',
  'This box stays open so that you can mark one citation after another.': 'يبقى هذا المربع مفتوحاً حتى تتمكن من وضع علامة على اقتباس تلو الآخر.',
  'This box stays open so that you can mark one entry after another.': 'يبقى هذا المربع مفتوحاً حتى تتمكن من وضع علامة على إدخال تلو الآخر.',
  'This build cannot sign in to that provider.': 'لا يمكن لهذا الإصدار تسجيل الدخول إلى ذلك الموفر.',
