  'This calendar comes from an account — remove the account to remove its calendars.': 'يأتي هذا التقويم من حساب — قم بإزالة الحساب لإزالة تقويماته.',
  'This cannot be undone.': 'لا يمكن التراجع عن هذا الإجراء.',
  'This cell has a comment. Reply to it, or delete it, before adding a note.': 'تحتوي هذه الخلية على تعليق. قم بالرد عليه أو حذفه قبل إضافة ملاحظة.',
  'This cell has a note. Delete it, or edit it, to comment here instead.': 'تحتوي هذه الخلية على ملاحظة. احذفها أو حرّرها لإضافة تعليق هنا بدلاً منها.',
  'This cell has a note. Delete the note, or edit it, before starting a comment here.': 'تحتوي هذه الخلية على ملاحظة. احذف الملاحظة أو حرّرها قبل بدء تعليق هنا.',
  'This cell is merged down its column — unmerge it before splitting it.': 'هذه الخلية مدمجة على امتداد عمودها — قم بإلغاء دمجها قبل تقسيمها.',
  'This cell is not merged — there is nothing to split.': 'هذه الخلية غير مدمجة — لا يوجد ما يمكن تقسيمه.',
  'This cell reads no other cell': 'لا تشير هذه الخلية إلى أي خلية أخرى',
