  'This document is protected for filling in forms: only its form fields can be changed.': 'هذا المستند محمي لتعبئة النماذج: لا يمكن تغيير سوى حقول النماذج فيه.',
  'This document is protected from unintentional editing. You may edit in this region.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك التحرير في هذه المنطقة.',
  'This document is protected from unintentional editing. You may edit it, and every change is tracked.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك تحريره، ويتم تعقب كل تغيير.',
  'This document is protected from unintentional editing. You may edit it; formatting is limited to styles.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك تحريره؛ ويقتصر التنسيق على الأنماط.',
  'This document is protected from unintentional editing. You may only fill in forms in this region.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك فقط تعبئة النماذج في هذه المنطقة.',
  'This document is protected from unintentional editing. You may only insert comments into this region.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك فقط إدراج تعليقات في هذه المنطقة.',
  'This document is protected from unintentional editing. You may only view this region.': 'هذا المستند محمي من التحرير غير المقصود. يمكنك فقط عرض هذه المنطقة.',
  'This document is protected: formatting is limited to styles.': 'هذا المستند محمي: يقتصر التنسيق على الأنماط.',
  'This document is protected: only comments can be added here.': 'هذا المستند محمي: لا يمكن هنا سوى إضافة تعليقات.',
  'This document is protected: only comments can be added here. Review → Restrict Editing shows the regions you can edit.': 'هذا المستند محمي: لا يمكن هنا سوى إضافة تعليقات. اختر مراجعة ← تقييد التحرير لعرض المناطق التي يمكنك تحريرها.',
