  'This is the first time this deck has been open on this computer, so there is nothing to compare it with yet. Next time, whatever is new in the file is listed here.': 'هذه هي المرة الأولى التي يُفتح فيها هذا العرض التقديمي على هذا الكمبيوتر، لذا لا يوجد ما تتم مقارنته به بعد. في المرة القادمة، سيُدرج هنا كل ما هو جديد في الملف.',
  'This is the latest release.': 'هذا هو أحدث إصدار.',
