  'This letter takes its recipients from {name}. Attach the list?': 'تأخذ هذه الرسالة مستلميها من {name}. هل تريد إرفاق القائمة؟',
  'This letter\'s recipient list is on a network share ({path}), so it is not opened from the letter. Select Recipients → Use an Existing List to choose it.': 'قائمة مستلمي هذه الرسالة موجودة على مجلد مشترك على الشبكة ({path})، لذا لا يتم فتحها من الرسالة. اختر تحديد المستلمين ← استخدام قائمة موجودة لاختيارها.',
  'This list has no subtotals to remove': 'لا تحتوي هذه القائمة على إجماليات فرعية لإزالتها',
