  'This photo keeps its turn where it cannot be changed without redrawing it. Edit opens it in Image, which can.': 'دوران هذه الصورة محفوظ بطريقة لا يمكن تغييرها دون إعادة رسمها. يفتحها الأمر «تحرير» في محرر الصور، الذي يستطيع ذلك.',
