  '{count} slide is different since this deck was last open here (last saved by {person}) — Review → Show Changes lists them.': { zero: 'لم تتغير أي شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — يمكنك التحقق في مراجعة ← إظهار التغييرات.', one: 'تغيّرت شريحة واحدة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — تجدها في مراجعة ← إظهار التغييرات.', two: 'تغيّرت شريحتان منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — تجدهما في مراجعة ← إظهار التغييرات.', few: 'تغيّرت {count} شرائح منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — تجدها في مراجعة ← إظهار التغييرات.', many: 'تغيّرت {count} شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — تجدها في مراجعة ← إظهار التغييرات.', other: 'تغيّرت {count} شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا (آخر من حفظه: {person}) — تجدها في مراجعة ← إظهار التغييرات.' },
  '{count} slide is different since this deck was last open here — Review → Show Changes lists them.': { zero: 'لم تتغير أي شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — يمكنك التحقق في مراجعة ← إظهار التغييرات.', one: 'تغيّرت شريحة واحدة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — تجدها في مراجعة ← إظهار التغييرات.', two: 'تغيّرت شريحتان منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — تجدهما في مراجعة ← إظهار التغييرات.', few: 'تغيّرت {count} شرائح منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — تجدها في مراجعة ← إظهار التغييرات.', many: 'تغيّرت {count} شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — تجدها في مراجعة ← إظهار التغييرات.', other: 'تغيّرت {count} شريحة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا — تجدها في مراجعة ← إظهار التغييرات.' },
